    if (!force && have && !have.provisional && Date.now() - have.fetched < TASKS_FRESH_MS) return;
    if (!force && Date.now() - (state.tasksAsked[day] || 0) < 15000) return;   /* a safety net: never a fetch loop */
    state.tasksAsked[day] = Date.now();
