    try { navigator.clipboard.writeText(text).catch(function () {}); } catch (e) { /* clipboard not allowed */ }
    var a = document.createElement("a");
    a.href = "https://claude.ai/new?q=" + encodeURIComponent(pr.link);
    a.target = "_blank"; a.rel = "noopener";
