      var er = $("clErr"); if (er) er.textContent = mine.saveErr || "";
      var more = Object.keys(logDrafts).some(function (k) { return k !== d || logDrafts[k].text !== text; });
      if ((mine.again || more) && !mine.saveErr) { mine.again = false; logSave(pin); }
