  /* --- state and colour --- */
  function hsvRgb(h, s) { s /= 100; var f = function (n) { var k = (n + h / 60) % 6; return 1 - s * Math.max(0, Math.min(k, 4 - k, 1)); }; return [f(5), f(3), f(1)].map(function (v) { return Math.round(v * 255); }); }
