      var nm = t.value.trim().toUpperCase().slice(0, 30);
      if (nm) { lsSet(LS_HAGROUPS, haGroups().map(function (g) { return g.id === t.dataset.hagname ? { id: g.id, nm: nm } : g; })); render(true); }
