  function ibWaiting() { return ((ib.data && ib.data.waiting) || []).filter(function (n) { return !ib.q[n.id]; }); }
  function ibKept() { return ((ib.data && ib.data.kept) || []).filter(function (n) { return !ib.q[n.id] || ib.q[n.id].status === "kept"; }); }
